content.text:
The evidence points to one root cause: payment went down during the incident and checkout's payment calls all failed. I'm stopping here with the evidence in hand.

```json
{
  "root_causes": [
    {
      "service": "payment",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) AS n, round(approx_quantile(duration,0.5)/1e6,3) AS p50_ms FROM abnormal_traces WHERE span_name LIKE '%PaymentService/Charge%' GROUP BY ALL",
          "claim": "All checkout-to-payment Charge calls in the abnormal window returned Error in about 0.13 ms; no payment-side spans exist."
        },
        {
          "kind": "metric",
          "sql": "SELECT strftime(time, '%H:%M:%S') AS t, count(*) AS n, round(avg(value)/1e6,1) AS mem_mb FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'payment%' AND metric='container.memory.usage' GROUP BY ALL ORDER BY 1",
          "claim": "Payment memory fell from about 111 MB to 2.7 MB around 08:56 and stayed there for the rest of the window."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name AS pod, metric, round(min(value),1) AS minv, round(max(value),1) AS maxv, count(*) AS n FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'payment%' AND metric='k8s.container.restarts' GROUP BY ALL",
          "claim": "Payment container restart counter moved from 0 to 1 inside the abnormal window; normal period stayed at 0."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, count(*) AS n FROM abnormal_traces WHERE service_name='payment' GROUP BY ALL",
          "claim": "Payment emits no spans in the abnormal window, against 32 in normal, so it stopped serving requests."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "payment",
      "to": "checkout",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS parent_svc, p.span_name AS parent_span, c.span_name AS child_span, c.attr_status_code AS child_status, count(*) AS n FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.span_name LIKE '%PaymentService/Charge%' GROUP BY ALL",
          "claim": "Charge is a child of checkout's PlaceOrder span, and every such Charge span is Error, so PlaceOrder fails."
        }
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) AS n FROM abnormal_traces WHERE span_name IN ('oteldemo.CheckoutService/PlaceOrder','grpc.oteldemo.CheckoutService/PlaceOrder','POST /api/checkout') GROUP BY ALL",
          "claim": "Checkout PlaceOrder errors are about 46 spans; frontend's gRPC PlaceOrder client and POST /api/checkout spans return Error/500 in step."
        }
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='frontend-proxy' AND span_name IN ('ingress','router frontend egress') AND attr_http_response_status_code = 500 GROUP BY ALL",
          "claim": "Frontend-proxy ingress and egress spans return HTTP 500 for about 116 and 106 requests, tracking frontend's checkout failures."
        }
      ]
    }
  ]
}
```
